package com.bank;import java.sql.*;public class BankingDao{public void saveCustomer(Customer c)throws SQLException{try(Connection x=DBConnection.get();PreparedStatement p=x.prepareStatement("INSERT INTO customers VALUES(?,?,?,?,?,?)")){p.setInt(1,c.getCustomerId());p.setString(2,c.getName());p.setString(3,c.getEmail());p.setString(4,c.getCity());p.setString(5,c.getPhone());p.setString(6,c.getCustomerType());p.executeUpdate();}}public void atomicTransfer(long from,long to,double amount)throws SQLException{try(Connection x=DBConnection.get()){x.setAutoCommit(false);try(PreparedStatement debit=x.prepareStatement("UPDATE accounts SET balance=balance-? WHERE account_number=?");PreparedStatement credit=x.prepareStatement("UPDATE accounts SET balance=balance+? WHERE account_number=?")){debit.setDouble(1,amount);debit.setLong(2,from);credit.setDouble(1,amount);credit.setLong(2,to);if(debit.executeUpdate()!=1||credit.executeUpdate()!=1)throw new SQLException("Invalid account");x.commit();}catch(Exception e){x.rollback();throw e;}}}}